import openpyxl

wb = openpyxl.load_workbook('output.xlsx')

# Build lookup from ITEMS: S.N -> ITEM
items = {}
ws_items = wb['ITEMS']
for row in ws_items.iter_rows(min_row=2, max_row=ws_items.max_row, max_col=2):
    sn = row[0].value
    item = row[1].value
    if sn is not None:
        items[sn] = item

for ws_name in ['SHEET1', 'SHEET2']:
    ws = wb[ws_name]
    for row in ws.iter_rows(min_row=2, max_row=ws.max_row, max_col=2):
        sn = row[0].value
        if sn in items:
            row[1].value = items[sn]

wb.save('output.xlsx')
print("done")
